mapper.select:
SELECT EMAIL , NAME , NICKNAME , PASSWORD , TO_CHAR(REGIST_DATE, 'YYYY-MM-DD HH24:MI:SS') AS REGIST_DATE , TO_CHAR(MODIFY_DATE, 'YYYY-MM-DD HH24:MI:SS') AS MODIFY_DATE , TO_CHAR(LATEST_LOGIN_SUCCESS_DATE, 'YYYY-MM-DD HH24:MI:SS') AS LATEST_LOGIN_SUCCESS_DATE , TO_CHAR(LATEST_LOGIN_FAIL_DATE, 'YYYY-MM-DD HH24:MI:SS') AS LATEST_LOGIN_FAIL_DATE , TO_CHAR(LATEST_LOGOUT_DATE, 'YYYY-MM-DD HH24:MI:SS') AS LATEST_LOGOUT_DATE , LOGIN_FAIL_COUNT , LOGIN_BLOCK_YN , TO_CHAR(LOGIN_BLOCK_DATE, 'YYYY-MM-DD HH24:MI:SS') AS LOGIN_BLOCK_DATE , LOGIN_YN , SALT , DEL_YN FROM MEMBERS m WHERE DEL_YN = 'N'
AND m.EMAIL = #{email}
AND AES_DECRYPTION(m.NAME) = #{name}
AND AES_DECRYPTION(m.NICKNAME) LIKE '%' || #{nickname} || '%'
AND TO_CHAR(REGIST_DATE,'YYYY-MM-DD') = #{registDate}
